import {RoundedBoxGeometry} from './vendor/addons/geometries/RoundedBoxGeometry.js';
import * as THREE from './vendor/three.module.js';
import {mesh,ball,tube,material} from './render-kit.js';
export function laughingFace(parent,{y=2.3,z=.4,width=.31,height=.34,sculpted=false,lipRadius=null,lipColor=null,archedTeeth=false}={}){
 const face=new THREE.Group();face.position.set(0,y,z);parent.add(face);face.name='laugh-face';
 const shape=new THREE.Shape();shape.moveTo(-width,.075);shape.bezierCurveTo(-width*.6,.01,width*.6,.01,width,.075);shape.bezierCurveTo(width*.94,-height*.85,width*.55,-height,0,-height);shape.bezierCurveTo(-width*.55,-height,-width*.94,-height*.85,-width,.075);
 const inside=material('#301b14',.84);const cavity=sculpted?mesh(face,new THREE.SphereGeometry(1,48,32,Math.PI,Math.PI),new THREE.MeshStandardMaterial({color:'#26140e',roughness:.9,side:THREE.BackSide}),[0,-height*.43,0],[width,height*.56,.23]):mesh(face,new THREE.ExtrudeGeometry(shape,{depth:.025,bevelEnabled:true,bevelSize:.014,bevelThickness:.012,bevelSegments:4,curveSegments:32}),inside,[0,0,0]);cavity.name='mouth-cavity';
 const rim=tube(face,lipColor||(sculpted?'#d0aa39':'#a27629'),sculpted?Array.from({length:33},(_,i)=>{const a=i/32*Math.PI*2;return [Math.cos(a)*width,-height*.43+Math.sin(a)*height*.56,.006];}):[[-width,.075,.018],[-width*.85,-height*.5,.016],[0,-height,.018],[width*.85,-height*.5,.016],[width,.075,.018]],lipRadius??(sculpted?.009:.014),96,12);
 const upper=new THREE.Group();face.add(upper);upper.name='upper-teeth';for(let i=0;i<8;i++){const x=(i-3.5)*width*.215,yy=archedTeeth?-height*.43+Math.sqrt(1-(x/width)**2)*height*.56-.022:sculpted?.014-.028*(Math.abs(i-3.5)/3.5)**2:.035+.036*(Math.abs(i-3.5)/3.5)**2;const tooth=new THREE.Mesh(new RoundedBoxGeometry(width*.22,.043,.025,3,.008),material('#fff7de',.38));tooth.position.set(x,yy,sculpted?.025:.043);tooth.rotation.z=(i-3.5)*.032;upper.add(tooth);}
 const jaw=new THREE.Group();jaw.name='laugh-jaw';face.add(jaw);for(let i=0;i<6;i++){const x=(i-2.5)*width*.215,yy=-height+.045+.048*(Math.abs(i-2.5)/2.5)**2;ball(jaw,'#f9eccc',[x,yy,.036],[width*.115,.027,.022]);}ball(jaw,'#bc7d6f',[0,-height*.72,.042],[width*.43,.046,.022]);
 face.visible=false;face.userData={jaw,cavity,rim,height,sculpted};return face;
}
export function animateLaugh(face,time,motion=1){const d=face.userData;if(!d?.jaw)return;const syllable=Math.sin(time*10.5),open=d.sculpted?.98+.035*syllable*motion:.92+.14*syllable*motion;face.scale.set(d.fixedAperture?1:1+Math.sin(time*5.25)*.025*motion,d.fixedAperture?1:open,1);d.jaw.position.y=-.012*(1+syllable)*motion;d.jaw.rotation.x=.12*syllable*motion;}
const faceGrids=new Map();
export function conformFace(face,surface,{width=.34,height=.5,cacheKey=null}={}){
 const nx=9,ny=12,minY=-height-.07,maxY=.13,values=faceGrids.get(cacheKey)||[];if(!values.length){for(let y=0;y<=ny;y++)for(let x=0;x<=nx;x++)values.push(surface(face.position.x-width+x/nx*width*2,face.position.y+minY+y/ny*(maxY-minY)));if(cacheKey)faceGrids.set(cacheKey,values);}
 const sample=(x,y)=>{const u=Math.max(0,Math.min(nx-.0001,(x+width)/(width*2)*nx)),v=Math.max(0,Math.min(ny-.0001,(y-minY)/(maxY-minY)*ny)),ix=Math.floor(u),iy=Math.floor(v),a=values[ix+iy*(nx+1)],b=values[ix+1+iy*(nx+1)],c=values[ix+(iy+1)*(nx+1)],d=values[ix+1+(iy+1)*(nx+1)];return THREE.MathUtils.lerp(THREE.MathUtils.lerp(a,b,u-ix),THREE.MathUtils.lerp(c,d,u-ix),v-iy);};
 face.updateMatrixWorld(true);const inverse=face.matrixWorld.clone().invert(),point=new THREE.Vector3();face.traverse(o=>{if(!o.isMesh)return;const relative=new THREE.Matrix4().multiplyMatrices(inverse,o.matrixWorld),back=relative.clone().invert();o.geometry=o.geometry.clone();const attr=o.geometry.attributes.position;for(let i=0;i<attr.count;i++){point.fromBufferAttribute(attr,i).applyMatrix4(relative);point.z+=sample(point.x,point.y)-face.position.z+.012;point.applyMatrix4(back);attr.setXYZ(i,point.x,point.y,point.z);}attr.needsUpdate=true;o.geometry.computeVertexNormals();o.geometry.computeBoundingSphere();o.castShadow=false;});face.userData.conformed=true;
}
